{"inp":{"code":"# Using previously computed numbers
shares = 1_102_810_216  # shares implied by current market cap / price
ND = 4.278934e10
EBITDA = 1.1809655988e10  # implied EBITDA from previous calculation

def price_from_ev_ebitda(target_ev_ebitda):
    EV_target = EBITDA * target_ev_ebitda
    marketcap_target = EV_target - ND
    price_target = marketcap_target / shares
    return EV_target, marketcap_target, price_target

candidates = [7.2, 7.9, 8.5]
results = {}
for m in candidates:
    evt, mkt, pt = price_from_ev_ebitda(m)
    results[m] = {'EV_target': evt, 'MarketCap_target': mkt, 'Price_target': pt}

results
